import { getContext, setContext } from 'svelte';
import type { BrushProps } from './types.js';

const BRUSH_SLOT_KEY = Symbol('evilcharts.brush-slot');

/**
 * Registry for the declarative `<Chart.Brush />` child.
 *
 * The reference pulls the `<Brush>` element out of `children` with
 * `React.Children.toArray(...).find(...)`. Svelte cannot inspect a snippet, so the slot
 * registers itself into this context instead — the config-slot pattern from
 * plans/SPEC.md §4.2. Every cartesian chart root creates one.
 */
export class BrushSlotRegistry {
	#token: string | null = null;

	slot = $state<BrushProps | null>(null);

	get present() {
		return this.slot !== null;
	}

	/**
	 * Registration is keyed by a per-instance token: LayerChart's `<Chart>` wraps its content in
	 * `{#key isMounted}`, so the subtree remounts once on mount and the old instance's teardown can
	 * run after the new instance has registered. Ignoring a stale teardown keeps the live
	 * registration intact. See plans/DEVIATIONS.md A-3.
	 */
	register(token: string, props: BrushProps) {
		this.#token = token;
		this.slot = props;
	}

	unregister(token: string) {
		if (this.#token !== token) return;
		this.#token = null;
		this.slot = null;
	}
}

export function setBrushSlotContext() {
	const registry = new BrushSlotRegistry();
	setContext(BRUSH_SLOT_KEY, registry);
	return registry;
}

export function useBrushSlot() {
	const registry = getContext<BrushSlotRegistry | undefined>(BRUSH_SLOT_KEY);

	if (!registry) {
		throw new Error('<Brush /> must be used within an Evil chart root');
	}

	return registry;
}

import type { DragType, EvilBrushRange } from './types.js';

/**
 * Keeps a range inside `[0, totalPoints - 1]` while preserving `minSpan`.
 *
 * Extracted from the reference's `clampRange` useCallback so the boundary rules are unit
 * testable; the logic is unchanged. `mode` matters because which edge gives way depends on
 * which handle the pointer is dragging.
 */
export function clampRange(
	range: EvilBrushRange,
	{ totalPoints, minSpan, mode }: { totalPoints: number; minSpan: number; mode?: DragType }
): EvilBrushRange {
	let { startIndex, endIndex } = range;
	const maxIndex = Math.max(0, totalPoints - 1);

	startIndex = Math.max(0, Math.min(startIndex, maxIndex));
	endIndex = Math.max(0, Math.min(endIndex, maxIndex));

	if (mode === 'left') {
		const maxStart = Math.max(0, endIndex - minSpan);
		startIndex = Math.min(startIndex, maxStart);
		return { startIndex, endIndex };
	}

	if (mode === 'right') {
		const minEnd = Math.min(maxIndex, startIndex + minSpan);
		endIndex = Math.max(endIndex, minEnd);
		return { startIndex, endIndex };
	}

	if (endIndex - startIndex < minSpan) {
		endIndex = Math.min(startIndex + minSpan, maxIndex);
		if (endIndex - startIndex < minSpan) {
			startIndex = Math.max(0, endIndex - minSpan);
		}
	}
	return { startIndex, endIndex };
}

/** Pans a range by `delta` indices, clamped to the dataset without changing its span. */
export function panRange(
	origin: EvilBrushRange,
	delta: number,
	totalPoints: number
): EvilBrushRange {
	const span = origin.endIndex - origin.startIndex;
	let s = origin.startIndex + delta;
	let e = s + span;
	if (s < 0) {
		s = 0;
		e = span;
	}
	if (e > totalPoints - 1) {
		e = totalPoints - 1;
		s = Math.max(0, e - span);
	}
	return { startIndex: s, endIndex: e };
}

export { default as Brush } from './brush.svelte';
export { default as EvilBrush } from './evil-brush.svelte';
export { default as BrushHandle } from './brush-handle.svelte';
export { default as MiniChart } from './mini-chart.svelte';
export { BrushDrag, type BrushDragHandlers } from './use-brush-drag.svelte.js';
export { EvilBrushState } from './use-evil-brush.svelte.js';
export { BrushSlotRegistry, setBrushSlotContext, useBrushSlot } from './brush-slot.svelte.js';
export {
	SPRING_CONFIG,
	type BrushProps,
	type DragType,
	type EvilBrushProps,
	type EvilBrushRange,
	type EvilBrushVariant
} from './types.js';

import type { CurveType } from '../layerchart-chart/curves.js';
import type { ChartConfig } from '../layerchart-chart/chart-config.js';

// ─── Types ──────────────────────────────────────────────────────────────────

export type EvilBrushVariant = 'line' | 'area' | 'bar';

export interface EvilBrushRange {
	startIndex: number;
	endIndex: number;
}

// ─── Brush marker — the declarative `<Chart.Brush/>` child ─────────────────────
// Renders nothing; its PRESENCE turns the brush footer on (replacing the old
// showBrush prop) and its props carry the brush's height, handle-label
// formatter, and range callback. Shared so every cartesian chart attaches the
// SAME component to its root.

export interface BrushProps {
	height?: number; // brush preview strip height in px
	formatLabel?: (value: unknown, index: number) => string; // formats the range-handle labels
	onChange?: (range: EvilBrushRange) => void; // fires as the range moves
}

export type StrokeVariant = 'solid' | 'dashed' | 'animated-dashed';

export interface EvilBrushProps {
	/** Full dataset – always rendered in the miniature chart */
	data: Record<string, unknown>[];
	/** Chart config with colour definitions */
	chartConfig: ChartConfig;
	/** Data keys to plot (default: all keys from chartConfig) */
	dataKeys?: string[];
	/** X-axis data key – used for handle labels */
	xDataKey?: string;
	/** Visual variant of the mini chart */
	variant?: EvilBrushVariant;
	/** Pixel height of the brush */
	height?: number;
	/** Extra class */
	class?: string;
	/** Whether areas/bars should be stacked in the mini chart */
	stacked?: boolean;
	/** Stroke variant for line / area strokes in the mini chart */
	strokeVariant?: StrokeVariant;
	/** Whether to connect null data points in line / area variants */
	connectNulls?: boolean;
	/** Radius for bar corners in the bar variant */
	barRadius?: number;

	// ── Controlled mode ──────────────────────────────────────────────────
	/** Controlled start index */
	startIndex?: number;
	/** Controlled end index */
	endIndex?: number;

	// ── Uncontrolled mode ────────────────────────────────────────────────
	/** Initial start index (uncontrolled) */
	defaultStartIndex?: number;
	/** Initial end index (uncontrolled) */
	defaultEndIndex?: number;

	/** Fired whenever the visible range changes */
	onChange?: (range: EvilBrushRange) => void;
	/** Format the handle label from the xDataKey value */
	formatLabel?: (value: unknown, index: number) => string;
	/** Curve type for line / area variants */
	curveType?: CurveType;
	/** Minimum number of data points that must remain selected */
	minSpan?: number;
	/** Whether to render labels on the handles */
	showLabels?: boolean;
	/** Skip rendering own ChartStyle (when inside a ChartContainer that already provides CSS vars) */
	skipStyle?: boolean;
}

// ─── Pointer-capture drag ───────────────────────────────────────────────────
// Uses the modern Pointer Events API. setPointerCapture routes all pointer
// events to the originating element, so we get mouse + touch + pen support with
// zero global listeners.

export type DragType = 'left' | 'right' | 'middle';

export interface DragState {
	type: DragType;
	originX: number;
	originRange: EvilBrushRange;
}

// ─── Spring config ──────────────────────────────────────────────────────────

export const SPRING_CONFIG = { stiffness: 300, damping: 35, mass: 0.8 };

/**
 * The mini chart pins its bars to a fixed width with a small gap, matching the reference's
 * `<BarChart barGap={2} barSize={14}>`.
 */
export const MINI_BAR_SIZE = 14;
export const MINI_BAR_GAP = 2;

import { panRange } from './clamp.js';
import type { DragState, DragType, EvilBrushRange } from './types.js';

type Options = {
	range: () => EvilBrushRange;
	totalPoints: () => number;
	container: () => HTMLDivElement | undefined;
	commit: (next: EvilBrushRange, mode?: DragType) => void;
};

export type BrushDragHandlers = {
	onpointerdown: (event: PointerEvent) => void;
	onpointermove: (event: PointerEvent) => void;
	onpointerup: (event: PointerEvent) => void;
	onpointercancel: (event: PointerEvent) => void;
	onlostpointercapture: (event: PointerEvent) => void;
};

/**
 * Pointer-capture drag state for the brush handles and the pannable selection.
 *
 * A direct port of the reference's `useBrushDrag`: the same index-delta maths, the same
 * three drag modes, and the same `setPointerCapture` routing so mouse, touch and pen all
 * work without global listeners.
 */
export class BrushDrag {
	#drag: DragState | null = null;
	#options: Options;

	isDragging = $state(false);

	constructor(options: Options) {
		this.#options = options;
	}

	#toIndexDelta(px: number) {
		const container = this.#options.container();
		const totalPoints = this.#options.totalPoints();
		if (!container || totalPoints <= 1) return 0;
		return Math.round((px / container.getBoundingClientRect().width) * (totalPoints - 1));
	}

	#onPointerDown(event: PointerEvent, type: DragType) {
		event.preventDefault();
		(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);
		this.#drag = { type, originX: event.clientX, originRange: { ...this.#options.range() } };
		this.isDragging = true;
	}

	#onPointerMove = (event: PointerEvent) => {
		const d = this.#drag;
		if (!d) return;

		const delta = this.#toIndexDelta(event.clientX - d.originX);
		const { type, originRange: o } = d;
		const totalPoints = this.#options.totalPoints();

		if (type === 'left') {
			this.#options.commit({ startIndex: o.startIndex + delta, endIndex: o.endIndex }, 'left');
		} else if (type === 'right') {
			this.#options.commit({ startIndex: o.startIndex, endIndex: o.endIndex + delta }, 'right');
		} else {
			this.#options.commit(panRange(o, delta, totalPoints), 'middle');
		}
	};

	#finishDrag = (event: PointerEvent) => {
		const target = event.currentTarget as HTMLElement;
		if (target.hasPointerCapture(event.pointerId)) target.releasePointerCapture(event.pointerId);
		this.#drag = null;
		this.isDragging = false;
	};

	/** Binds all three pointer handlers for a given drag type. */
	bind(type: DragType): BrushDragHandlers {
		return {
			onpointerdown: (event: PointerEvent) => this.#onPointerDown(event, type),
			onpointermove: this.#onPointerMove,
			onpointerup: this.#finishDrag,
			onpointercancel: this.#finishDrag,
			onlostpointercapture: this.#finishDrag
		};
	}
}

import type { EvilBrushRange } from './types.js';

/**
 * Owns the visible-range state a cartesian chart root feeds its `<EvilBrush>` footer.
 *
 * Port of the reference's `useEvilBrush`. React's `useDeferredValue` (used there to keep the
 * handles at pointer cadence while the expensive chart re-render lags) has no Svelte
 * counterpart and is not needed: Svelte updates only the marks that actually changed.
 * See plans/DEVIATIONS.md B-5.
 */
export class EvilBrushState<TData extends Record<string, unknown>> {
	#getData: () => TData[];
	range = $state<EvilBrushRange>({ startIndex: 0, endIndex: 0 });

	constructor(options: {
		data: () => TData[];
		defaultStartIndex?: number;
		defaultEndIndex?: number;
	}) {
		this.#getData = options.data;
		const data = options.data();
		this.range = {
			startIndex: options.defaultStartIndex ?? 0,
			endIndex: options.defaultEndIndex ?? Math.max(0, data.length - 1)
		};

		// The reference resets the range whenever the dataset length changes.
		let lastLength = data.length;
		$effect(() => {
			const length = this.#getData().length;
			if (length === lastLength) return;
			lastLength = length;
			this.range = { startIndex: 0, endIndex: Math.max(0, length - 1) };
		});
	}

	get visibleData() {
		return this.#getData().slice(this.range.startIndex, this.range.endIndex + 1);
	}

	get brushProps() {
		return {
			startIndex: this.range.startIndex,
			endIndex: this.range.endIndex,
			onChange: (range: EvilBrushRange) => {
				this.range = range;
			}
		};
	}
}
